import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { createServer } from "node:http";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { openStore } from "../src/store.js";
import { createApp } from "../src/app.js";

let dir, file, server, base;

async function start() {
  const store = await openStore(file);
  server = createServer(createApp(store));
  await new Promise((r) => server.listen(0, r));
  base = `http://localhost:${server.address().port}`;
}
const stop = () => new Promise((r) => server.close(r));

const post = (path, fields = {}, headers = {}) =>
  fetch(base + path, {
    method: "POST",
    body: new URLSearchParams(fields),
    headers: { "Content-Type": "application/x-www-form-urlencoded", ...headers },
    redirect: "manual",
  });

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), "books-"));
  file = join(dir, "books.json");
  await start();
});
afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe("books app", () => {
  it("shows empty sections on first open", async () => {
    const html = await (await fetch(base + "/")).text();
    expect(html).toContain("Currently reading");
    expect(html).toContain("Finished");
    expect(html).toContain("Nothing on the go.");
  });

  it("adds a book and shows it on its own page", async () => {
    const res = await post("/books", { title: "Dune", author: "Frank Herbert", notes: "Spice <must> flow" });
    expect(res.status).toBe(303);
    const loc = res.headers.get("location");
    expect(loc).toMatch(/^\/books\/[\w-]+$/);

    const html = await (await fetch(base + loc)).text();
    expect(html).toContain("<h1>Dune</h1>");
    expect(html).toContain("Frank Herbert");
    expect(html).toContain("Spice &lt;must&gt; flow");
    expect(html).toContain(`${base}${loc}`); // share link

    const home = await (await fetch(base + "/")).text();
    const [reading, finished] = home.split("<h2>Finished</h2>");
    expect(reading).toContain("Dune");
    expect(finished).not.toContain("Dune");
  });

  it("rejects a book without title or author", async () => {
    const res = await post("/books", { title: "  ", author: "Someone" });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain("Title and author are required.");
    expect(html).toContain('value="Someone"');
  });

  it("marks a book finished", async () => {
    const loc = (await post("/books", { title: "Emma", author: "Jane Austen" })).headers.get("location");
    const res = await post(`${loc}/finish`);
    expect(res.status).toBe(303);
    expect(res.headers.get("location")).toBe("/");

    const home = await (await fetch(base + "/")).text();
    const [reading, finished] = home.split("<h2>Finished</h2>");
    expect(reading).not.toContain("Emma");
    expect(finished).toContain("Emma");
    expect(await (await fetch(base + loc)).text()).toContain("Finished ");
  });

  it("returns to the book page when finishing from it", async () => {
    const loc = (await post("/books", { title: "Emma", author: "Jane Austen" })).headers.get("location");
    const res = await post(`${loc}/finish`, {}, { Referer: base + loc });
    expect(res.headers.get("location")).toBe(loc);
  });

  it("404s for unknown books", async () => {
    expect((await fetch(base + "/books/nope")).status).toBe(404);
    expect((await post("/books/nope/finish")).status).toBe(404);
  });

  it("keeps books after a restart", async () => {
    const loc = (await post("/books", { title: "Middlemarch", author: "George Eliot", notes: "Long" })).headers.get("location");
    await post(`${loc}/finish`);
    const saved = JSON.parse(await readFile(file, "utf8"));
    expect(saved).toHaveLength(1);
    expect(saved[0]).toMatchObject({ title: "Middlemarch", status: "finished" });

    await stop();
    await start();
    const html = await (await fetch(base + loc)).text();
    expect(html).toContain("Middlemarch");
    expect(html).toContain("George Eliot");
  });
});

