import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import { randomBytes } from "node:crypto";

// Keeps books in memory and writes the whole list to a JSON file on every change.
export async function openStore(file) {
  let books = [];
  try {
    books = JSON.parse(await readFile(file, "utf8"));
  } catch (err) {
    if (err.code !== "ENOENT") throw err;
  }

  // Writes happen one at a time, and each goes to a temp file first,
  // so a crash can't leave a half-written books.json.
  let queue = Promise.resolve();
  function save() {
    const snapshot = JSON.stringify(books, null, 2);
    queue = queue.then(async () => {
      await mkdir(dirname(file), { recursive: true });
      const tmp = `${file}.${process.pid}.tmp`;
      await writeFile(tmp, snapshot);
      await rename(tmp, file);
    });
    return queue;
  }

  return {
    list() {
      return books;
    },
    get(id) {
      return books.find((b) => b.id === id);
    },
    async add({ title, author, notes }) {
      const book = {
        id: randomBytes(6).toString("base64url"),
        title,
        author,
        notes,
        status: "reading",
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await save();
      return book;
    },
    async finish(id) {
      const book = this.get(id);
      if (!book) return undefined;
      if (book.status !== "finished") {
        book.status = "finished";
        book.finishedAt = new Date().toISOString();
        await save();
      }
      return book;
    },
  };
}

const MAX_BODY = 64 * 1024;

const esc = (s) =>
  String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

const date = (iso) => (iso ? iso.slice(0, 10) : "");

function page(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  a { color: #2b5bab; }
  ul { list-style: none; padding: 0; }
  li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: .5rem 0; border-bottom: 1px solid #eee; }
  .muted { color: #777; }
  form.add { display: grid; gap: .5rem; margin-top: 1rem; }
  input, textarea, button { font: inherit; padding: .4rem; }
  textarea { min-height: 5rem; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: 1rem; border-radius: 4px; }
  .error { color: #b00020; }
</style>
</head>
<body>
${body}
</body>
</html>`;
}

function bookItem(b) {
  const finishBtn =
    b.status === "reading"
      ? `<form method="post" action="/books/${esc(b.id)}/finish"><button>Mark finished</button></form>`
      : `<span class="muted">${date(b.finishedAt)}</span>`;
  return `<li><span><a href="/books/${esc(b.id)}">${esc(b.title)}</a> <span class="muted">by ${esc(b.author)}</span></span>${finishBtn}</li>`;
}

function section(heading, books, empty) {
  const items = books.length ? `<ul>${books.map(bookItem).join("")}</ul>` : `<p class="muted">${empty}</p>`;
  return `<h2>${heading}</h2>${items}`;
}

function homePage(store, { error, values = {} } = {}) {
  const all = store.list();
  const reading = all.filter((b) => b.status === "reading");
  const finished = all
    .filter((b) => b.status === "finished")
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));
  return page(
    "My books",
    `<h1>My books</h1>
${section("Currently reading", reading, "Nothing on the go.")}
${section("Finished", finished, "No finished books yet.")}
<h2>Add a book</h2>
${error ? `<p class="error">${esc(error)}</p>` : ""}
<form class="add" method="post" action="/books">
  <label>Title <input name="title" required value="${esc(values.title)}"></label>
  <label>Author <input name="author" required value="${esc(values.author)}"></label>
  <label>Notes <textarea name="notes">${esc(values.notes)}</textarea></label>
  <button>Add book</button>
</form>`
  );
}

function bookPage(book, shareUrl) {
  const status =
    book.status === "finished"
      ? `Finished ${date(book.finishedAt)}`
      : `Reading since ${date(book.addedAt)}`;
  return page(
    book.title,
    `<p><a href="/">&larr; All books</a></p>
<h1>${esc(book.title)}</h1>
<p>by ${esc(book.author)}</p>
<p class="muted">${status}</p>
<h2>Notes</h2>
${book.notes ? `<div class="notes">${esc(book.notes)}</div>` : `<p class="muted">No notes.</p>`}
${book.status === "reading" ? `<form method="post" action="/books/${esc(book.id)}/finish"><button>Mark finished</button></form>` : ""}
<p class="muted">Share this book: <a href="${esc(shareUrl)}">${esc(shareUrl)}</a></p>`
  );
}

function send(res, status, html) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function notFound(res) {
  send(res, 404, page("Not found", `<h1>Not found</h1><p><a href="/">Back to my books</a></p>`));
}

function readForm(req) {
  return new Promise((resolve, reject) => {
    let body = "";
    req.setEncoding("utf8");
    req.on("data", (chunk) => {
      body += chunk;
      if (body.length > MAX_BODY) {
        reject(Object.assign(new Error("Body too large"), { status: 413 }));
        req.destroy();
      }
    });
    req.on("end", () => resolve(new URLSearchParams(body)));
    req.on("error", reject);
  });
}

export function createApp(store) {
  return async function handler(req, res) {
    try {
      const url = new URL(req.url, `http://${req.headers.host || "localhost"}`);
      const path = url.pathname;
      let m;

      if (path === "/" && req.method === "GET") {
        return send(res, 200, homePage(store));
      }

      if (path === "/books" && req.method === "POST") {
        const form = await readForm(req);
        const values = {
          title: (form.get("title") || "").trim(),
          author: (form.get("author") || "").trim(),
          notes: (form.get("notes") || "").trim(),
        };
        if (!values.title || !values.author) {
          return send(res, 400, homePage(store, { error: "Title and author are required.", values }));
        }
        const book = await store.add(values);
        return redirect(res, `/books/${book.id}`);
      }

      if ((m = path.match(/^\/books\/([\w-]+)$/)) && req.method === "GET") {
        const book = store.get(m[1]);
        if (!book) return notFound(res);
        return send(res, 200, bookPage(book, `${url.origin}/books/${book.id}`));
      }

      if ((m = path.match(/^\/books\/([\w-]+)\/finish$/)) && req.method === "POST") {
        const book = await store.finish(m[1]);
        if (!book) return notFound(res);
        const back = req.headers.referer && new URL(req.headers.referer, url.origin);
        return redirect(res, back && back.origin === url.origin ? back.pathname : "/");
      }

      return notFound(res);
    } catch (err) {
      if (err.status === 413) return send(res, 413, page("Too large", "<h1>That was too much text.</h1>"));
      console.error(err);
      send(res, 500, page("Error", "<h1>Something went wrong.</h1>"));
    }
  };
}

