  await new Promise((r) => server.listen(0, r));
  base = `http://localhost:${server.address().port}`;
}
const stop = () => new Promise((r) => server.close(r));

const post = (path, fields = {}, headers = {}) =>
  fetch(base + path, {
    method: "POST",
